package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;import javax.sound.midi.*;
public class ProductionTests {
 static int passed;static void check(boolean c,String m){if(!c)throw new AssertionError(m);passed++;}
 static double frequency(float[] audio,int start,int end){int crossings=0;for(int i=start+1;i<end;i++)if(audio[(i-1)*2]<=0&&audio[i*2]>0)crossings++;return crossings*Core.RATE/(double)(end-start);}
 static float[] process(Core.Source s,double speed,boolean preserve)throws Exception{ArrayList<Float> data=new ArrayList<>();TimeStretch.Sink sink=(l,r)->{data.add(l);data.add(r);};if(preserve)TimeStretch.preservePitch(s,speed,sink);else TimeStretch.resample(s,speed,sink);float[] out=new float[data.size()];for(int i=0;i<out.length;i++)out[i]=data.get(i);return out;}
 static float[] correct(Core.Source s,PitchCorrector.Config c)throws Exception{ArrayList<Float> values=new ArrayList<>();PitchCorrector.correct(s,c,(l,r)->{values.add(l);values.add(r);});float[] result=new float[values.size()];for(int i=0;i<result.length;i++)result[i]=values.get(i);return result;}
 public static void main(String[] args)throws Exception {
  Core.Source tone=new Core.Memory(StudioTests.wave(Core.RATE*2,440,.2));float[] stretched=process(tone,1.25,true),pitched=process(tone,1.25,false);check(stretched.length/2==76800&&pitched.length/2==76800,"Both tempo algorithms change duration");double kept=frequency(stretched,12000,65000),changed=frequency(pitched,12000,65000);System.out.println("Tempo tone frequencies: keep="+kept+", resample="+changed);check(Math.abs(kept-440)<5,"WSOLA preserves 440 Hz pitch");check(Math.abs(changed-550)<5,"Resampling changes pitch with speed");
  File dir=Files.createTempDirectory("studio-production-test").toFile();Core.Session project=new Core.Session();project.directory=dir.getPath();project.bpm=100;Core.Track t=new Core.Track("Vocal",0);Core.Clip clip=AudioIO.store(dir,StudioTests.wave(Core.RATE*2,440,.2),"Tone",48000);t.clips.add(clip);project.tracks.add(t);Core.Session faster=AudioIO.retimeProject(project,125,true);Core.Clip retimed=faster.tracks.get(0).clips.get(0);check(faster.bpm==125&&retimed.start==38400&&retimed.length==76800,"Project tempo changes clip positions and audio lengths");check(project.bpm==100&&clip.start==48000&&clip.length==96000&&new File(dir,clip.file).exists(),"Tempo edit keeps original session and sources for undo");AudioIO.save(faster);check(AudioIO.load(dir).bpm==125,"Retimed project reloads");
  float[] source=StudioTests.wave(Core.RATE*2,446,.2);PitchCorrector.Config correction=new PitchCorrector.Config();correction.strength=1;correction.retuneMs=0;float[] fixed=correct(new Core.Memory(source),correction);double before=frequency(source,18000,80000),after=frequency(fixed,18000,80000);System.out.println("Pitch correction tone frequencies: before="+before+", after="+after);check(fixed.length==source.length,"Pitch correction preserves timing");check(Math.abs(after-440)<Math.abs(before-440)&&Math.abs(after-440)<3,"Chromatic correction moves a detuned A toward 440 Hz");correction.strength=0;check(Arrays.equals(source,correct(new Core.Memory(source),correction)),"Zero strength is sample-identical bypass");check(PitchCorrector.nearest(66,0,1)==65&&PitchCorrector.nearest(68,9,2)==67,"Key/scale selection resolves disallowed notes");boolean refused=false;try{correct(new Core.Memory(new float[Core.RATE]),new PitchCorrector.Config());}catch(IOException e){refused=true;}check(refused,"Silence is not treated as a vocal note");
  Core.Session delay=StudioTests.session(new float[Core.RATE*2]);Core.Track dt=delay.tracks.get(0);dt.pan=0;Core.Memory impulse=(Core.Memory)dt.clips.get(0).source;impulse.data[0]=impulse.data[1]=.2f;dt.fx.delay=true;dt.fx.delaySync=false;dt.fx.leftMs=100;dt.fx.rightMs=200;dt.fx.delayFeedback=0;dt.fx.delayMix=.5;float[] stereoDelay=StudioTests.render(delay,Core.RATE);check(Math.abs(stereoDelay[4800*2])>.04&&Math.abs(stereoDelay[4800*2+1])<1e-5,"Left delay arrives at its independent 100 ms time");check(Math.abs(stereoDelay[9600*2+1])>.04&&Math.abs(stereoDelay[9600*2])<1e-5,"Right delay arrives at its independent 200 ms time");dt.fx.pingPong=true;dt.fx.delayFeedback=.6;float[] ping=StudioTests.render(delay,Core.RATE);check(Math.abs(ping[4800*2])>.04&&Math.abs(ping[14400*2+1])>.005,"Ping-pong routes feedback into the other channel");
  ArrayList<String> messages=new ArrayList<>();MidiParser parser=new MidiParser((s,a,b,stamp)->messages.add(s+":"+a+":"+b));parser.feed(new byte[]{(byte)144,60,100,61},0,4,0);parser.feed(new byte[]{110,(byte)248,60,0,(byte)176,64,127},0,7,0);check(messages.size()==4&&messages.get(1).equals("144:61:110")&&messages.get(2).equals("144:60:0"),"MIDI parser supports fragmented running status and realtime bytes");parser.feed(new byte[]{(byte)240,1,2,(byte)247,(byte)224,0,64},0,7,0);check(messages.get(messages.size()-1).equals("224:0:64"),"System-exclusive data does not corrupt subsequent pitch bend");
  Synth.Config config=Synth.factory(0);config.release=.05;SynthPoly poly=new SynthPoly(config);float[] block=new float[Core.RATE*2];poly.message(144,60,100);poly.message(144,64,100);poly.render(block,1000);check(poly.activeVoices==2&&StudioTests.rms(block,0,1000)>0,"MIDI notes render polyphonically");poly.message(176,64,127);poly.message(128,60,0);poly.render(block,5000);check(poly.activeVoices==2,"Sustain pedal holds released notes");poly.message(176,64,0);poly.render(block,10000);check(poly.activeVoices==1,"Releasing sustain releases deferred note-offs");poly.message(176,120,0);check(poly.activeVoices==0,"All sound off clears voices");
  MidiTake take=new MidiTake(config,100);take.recording=false;take.frames=24000;take.events.add(new MidiTake.Event(0,144,60,100));take.events.add(new MidiTake.Event(12000,144,64,90));take.events.add(new MidiTake.Event(24000,128,60,0));take.events.add(new MidiTake.Event(24000,128,64,0));ByteArrayOutputStream midi=new ByteArrayOutputStream();take.writeMidi(midi);Sequence sequence=MidiSystem.getSequence(new ByteArrayInputStream(midi.toByteArray()));check(sequence.getResolution()==480&&sequence.getTracks().length==1,"MIDI export is a valid single-track 480-PPQ file");check(sequence.getTracks()[0].size()>=6,"MIDI export retains tempo, note events and track end");File audio=new File(dir,"printed.pcm");try(AudioIO.Writer writer=new AudioIO.Writer(audio)){take.print((l,r)->writer.sample(l,r));}check(audio.length()>take.frames*8&&new AudioIO.Disk(audio).frames()>take.frames,"Recorded MIDI prints audio including release tail");

  File notesFile=new File(dir,"performance.mid");try(OutputStream out=new FileOutputStream(notesFile)){take.writeMidi(out);}Core.Clip midiClip=new Core.Clip("MIDI",new AudioIO.Disk(audio),audio.getName(),0);midiClip.midiFile=notesFile.getName();project.tracks.get(0).clips.add(midiClip);project.tracks.get(0).fx.delay=true;project.tracks.get(0).fx.leftMs=130;project.tracks.get(0).fx.rightMs=290;project.tracks.get(0).fx.delaySync=false;project.tracks.get(0).fx.pingPong=true;project.tracks.get(0).fx.delayFeedback=.6;AudioIO.save(project);Core.Session saved=AudioIO.load(dir);check(saved.tracks.get(0).fx.leftMs==130&&saved.tracks.get(0).fx.rightMs==290&&saved.tracks.get(0).fx.pingPong,"Stereo delay settings persist");check(saved.tracks.get(0).clips.get(1).midiFile.equals("performance.mid"),"MIDI source association persists");ByteArrayOutputStream backup=new ByteArrayOutputStream();AudioIO.backup(backup,project);File restoredDir=new File(dir,"backup-restored");restoredDir.mkdirs();Core.Session restored=AudioIO.restore(new ByteArrayInputStream(backup.toByteArray()),restoredDir);check(new File(restored.directory,"performance.mid").isFile(),"Project backup includes MIDI source");check(MidiSystem.getSequence(new File(restoredDir,"performance.mid")).getResolution()==480,"Restored MIDI source remains valid");
  Core.Clip corrected=clip.copy();String oldFile=corrected.file;AudioIO.correctClip(corrected,dir,new PitchCorrector.Config());check(!corrected.file.equals(oldFile)&&corrected.length==clip.length&&new File(dir,oldFile).exists(),"Pitch correction prints a new source and keeps the old one");
  Core.Session repeated=project.copy();Core.Clip duplicate=clip.copy();duplicate.start=150000;repeated.tracks.get(0).clips.add(duplicate);Core.Session rerate=AudioIO.retimeProject(repeated,120,false);check(rerate.tracks.get(0).clips.get(0).file.equals(rerate.tracks.get(0).clips.get(2).file),"Tempo processing deduplicates shared source files");

  boolean playable=true,released=true;float[] monitor=new float[Core.RATE*4];for(int patch=0;patch<Synth.NAMES.length;patch++){SynthPoly instrument=new SynthPoly(Synth.factory(patch));instrument.message(144,60,100);instrument.render(monitor,4800);double energy=0;for(int i=0;i<9600;i++){playable&=Float.isFinite(monitor[i])&&Math.abs(monitor[i])<=.7;energy+=monitor[i]*monitor[i];}playable&=energy>1e-6;instrument.message(128,60,0);instrument.render(monitor,Core.RATE*2);released&=instrument.activeVoices==0;}check(playable,"Every factory patch renders finite non-silent live MIDI audio");check(released,"Every live factory voice completes its release");
  System.out.println(passed+" tempo, pitch, stereo delay and MIDI checks passed.");
 }
}
